use std::collections::HashSet;

fn has_common_element(a: Vec<i32>, b: Vec<i32>) -> bool {
    // If either array is empty, they can't have common elements
    if a.is_empty() || b.is_empty() {
        return false;
    }
    
    // Convert the smaller array to a HashSet for efficiency
    let (shorter, longer) = if a.len() <= b.len() {
        (&a, &b)
    } else {
        (&b, &a)
    };
    
    let set: HashSet<i32> = shorter.iter().copied().collect();
    
    // Check if any element in the longer array exists in the set
    longer.iter().any(|&x| set.contains(&x))
}